"use strict";
(()=>{
 const select=document.getElementById('tableSelect'),facts=document.getElementById('tableFacts'),quiz=document.getElementById('tableQuizLink'),title=document.getElementById('tableReadyTitle'),status=document.getElementById('tableStatus'),hear=document.getElementById('hearWholeTable'),stop=document.getElementById('stopWholeTable');if(!select||!facts)return;
 const synth=window.speechSynthesis;
 const halt=(message=false)=>{if(synth)synth.cancel();if(stop)stop.disabled=true;if(message&&status)status.textContent='Sound stopped. You can hear the table again whenever you are ready.';};
 const speak=text=>{if(!synth||!window.SpeechSynthesisUtterance)return;halt(false);const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.76;u.onstart=()=>{if(stop)stop.disabled=false;};u.onend=()=>{if(stop)stop.disabled=true;if(status)status.textContent='Finished playing the table.';};u.onerror=()=>{if(stop)stop.disabled=true;};synth.speak(u)};
 for(let n=1;n<=20;n++){const o=document.createElement('option');o.value=n;o.textContent=n+' times table';select.append(o)}
 function render(){halt(false);const n=Number(select.value||1);facts.replaceChildren();for(let i=1;i<=10;i++){const card=document.createElement('article');card.className='table-fact-card';card.innerHTML='<strong>'+n+' × '+i+' = '+(n*i)+'</strong><button type="button" aria-label="Hear '+n+' times '+i+'">🔊</button>';card.querySelector('button').onclick=()=>{status.textContent='Playing '+n+' times '+i+'.';speak(n+' times '+i+' equals '+(n*i));};facts.append(card)}quiz.href='multiplication-tables-quiz.html?table='+n;quiz.textContent='Start '+n+' Times Table Quiz →';title.textContent='🎯 Ready for the '+n+' times table challenge?';status.textContent='';window.LearnWithUs?.recordComplete('multiplication-tables.html?table='+n)}
 select.addEventListener('change',render);hear.onclick=()=>{const n=Number(select.value);status.textContent='Playing the '+n+' times table from one to ten. Use Stop audio at any time.';speak(Array.from({length:10},(_,i)=>n+' times '+(i+1)+' equals '+(n*(i+1))).join('. '));};if(stop)stop.onclick=()=>halt(true);window.addEventListener('pagehide',()=>halt(false));const start=Math.min(20,Math.max(1,Number(new URLSearchParams(location.search).get('table'))||1));select.value=String(start);render();
})();
